const ROOT_CAUSES=['SUP_DELAY','DOC_LATE','QC_CYCLE_LONG','QC_FAIL','CHANGE_FREEZE','ALLOC_SHORT','DEMAND_CHANGE'];
const DEFAULT_RULES={otd:90,ready:75,price:10,certificate:90,change:60,invoice:5,stale:180,concentration:70,otif:90,asl:80,payment:30,workflow:98.5,sourcing:80};
function get(k,d){try{return JSON.parse(localStorage.getItem('p12-'+k))??d}catch{return d}}
function put(k,v){try{localStorage.setItem('p12-'+k,JSON.stringify(v))}catch{}}
const S={tabs:get('tabs',{}),views:get('views',{}),tabFilters:{},drill:null,filters:{},role:'Category Manager',rules:{...DEFAULT_RULES,...get('rules',{})},audit:get('audit',[]),tasks:get('tasks',[]),read:get('read',{}),reviewRequests:get('reviewRequests',[]),subscriptions:get('subscriptions',[]),selected:null,scope:'',compare:'net',delayMode:'amount',sort:'',drawer:null};
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=x=>Number(x)||0; const sum=(a,f=x=>x)=>(a||[]).reduce((s,x)=>s+N(f(x)),0);const unique=a=>[...new Set(a)];const fmt=(n,p=0)=>n==null||!Number.isFinite(Number(n))?'待接入':new Intl.NumberFormat('en-US',{maximumFractionDigits:p}).format(Number(n));
const money=n=>n==null?'需补字段':fmt(n,0)+' DEMO-USD';const pct=n=>n==null?'待接入':fmt(n,1)+'%';const days=(a,b)=>{if(!a||!b)return null;const aa=Date.parse(String(a).slice(0,10)),bb=Date.parse(String(b).slice(0,10));return Number.isFinite(aa)&&Number.isFinite(bb)?Math.round((aa-bb)/86400000):null};
const group=(rows,fun)=>(rows||[]).reduce((obj,row)=>{let key=String(fun(row)??'未分类');(obj[key]??=[]).push(row);return obj},{});
const derived=(rows,key,value=x=>1)=>Object.entries(group(rows,typeof key==='function'?key:x=>x[key])).map(([label,items])=>({label,value:sum(items,value),count:items.length,items}));
const q=(selector)=>document.querySelector(selector);
