function persist(){put('tabs',S.tabs);put('views',S.views);put('rules',S.rules);put('tasks',S.tasks);put('audit',S.audit);put('read',S.read);put('reviewRequests',S.reviewRequests);put('subscriptions',S.subscriptions)}
function log(action,id){S.audit.unshift({actor:'Anonymous demo',at:new Date().toISOString(),action,id,version:'kpi-v1.5',notice:'browser-only, not GxP'});persist()}
function popup(text){let t=document.getElementById('toast');if(t){t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}else console.info(text)}
function after(){if(typeof window.render==='function')window.render()}
function scopeData(){return EL.state.data}// G1: one and only canonical server/browser scoped analytical model
function detailRows(d){return d?.purchasing?.orders||[]}
function rowFilter(d,name){return d?.base?.dimensions?.[name+'s']||[]}
function metadata(d){return `数据截至 ${h(d.meta?.as_of||'2026-11-01')} · 数据源 ${h(d.meta?.data_scope?.startsWith('UPLOADED')?'上传工作簿 + 标注扩展数据':'内置模拟主数据')} · 口径版本 kpi-v1.5 (2026-11-01) · DEMO-USD · Non-GxP`}
function dataSelector(d,k,label){let vals=k==='month'?(d.base?.dimensions?.months||[]).map(x=>({id:x,label:x})):(d.base?.dimensions?.[k+'s']||[]);return `<label>${h(label)}<select data-p12-filter="${k}"><option value="">全部</option>${vals.map(x=>`<option value="${h(x.id)}" ${EL.state.filters[k]===x.id?'selected':''}>${h(x.label||x.name||x.id)}</option>`).join('')}</select></label>`}
function header(view,d){const isC=CONTROL.has(view);let tabs=TABS[view]||[];let sel=S.tabs[view]||tabs[0]?.[0];let control=isC?controls(view,d):`<div class="p12-filters">${dataSelector(d,'supplier','Supplier')}${dataSelector(d,'material','Material')}${dataSelector(d,'month','Month')}<label>金额口径<select data-p12-compare><option value="net" ${S.compare==='net'?'selected':''}>不含税采购额</option><option value="gross" ${window.PharmaV14?.hasBasis("gross",d)?"":"disabled"}>含税 · tax_rate</option><option value="landed" ${window.PharmaV14?.hasBasis("landed",d)?"":"disabled"}>落地成本 · 运费/关税</option></select></label><label>默认视图方案<select data-p12-role>${['Category Manager','Procurement Buyer','QA','Director'].map(x=>`<option ${S.role===x?'selected':''}>${h(x)}</option>`).join('')}</select></label>${btn('保存视图','save-view',true)}${btn('导出当前 PO','export:po',true)}${btn('重置筛选','reset',true)}</div>`;
return `<section class="e8-page p12-page"><header class="p12-page-head"><div><div class="p12-eyebrow"><button class="p13-crumb" data-p12="goto:overview">2026 › Procurement</button> › ${h(LABEL[view])} ${EL.state.filters.supplier?'› '+h(EL.state.filters.supplier):''}</div><h1>${h(LABEL[view])}</h1><span class="p12-subline">当前 ${fmt(d.overview.current.po_lines)} 条 PO / 全量 ${fmt(window.PharmaV14?.baselineRows()||d.overview.current.po_lines)} 条 PO · 数据源 ${h(d.meta?.data_scope||'模拟主数据')} · ${h(d.meta?.currency||'DEMO-USD')}</span></div><span class="p12-nongxp">模拟演示 · Non-GxP</span></header>${control}${tabs.length?`<nav class="p12-tabs" aria-label="业务分析视图">${tabs.map(([id,title])=>`<button class="${id===sel?'active':''}" data-p12="tab:${view}:${id}">${h(title)}</button>`).join('')}</nav>`:''}`}
function controls(view,d){let conf={workflow:['module','status'],reports:['template','period'],access:['role','status'],master:['object','validation'],alerts:['severity','source','read']};let opt={module:['全部','M02','M03','M04','M07'],status:['全部','Completed','Failed','Active','Review due'],template:['全部',...d.reports.templates.map(x=>x.name)],period:['全部','Weekly','Monthly'],role:['全部',...unique(d.access.users.map(x=>x.role))],object:['全部','Material','Supplier','Site'],validation:['全部','Valid','Missing'],severity:['全部','HIGH','MEDIUM','LOW'],source:['全部',...unique(d.notifications.alerts.map(x=>x.type))],read:['全部','未读','已读']};return `<div class="p12-filters">${(conf[view]||[]).map(field=>`<label>${h(field)}<select data-p12-local="${h(field)}"><option value="全部">全部</option>${opt[field].filter(x=>x!=='全部').map(x=>`<option ${S.tabFilters[field]===x?'selected':''}>${h(x)}</option>`).join('')}</select></label>`).join('')}${btn('清除本页筛选','clear-local',true)}</div>`}
function kpicard({name,value,unit='',target=null,base=null,delta=null,series=null,owner='',source='',key='',rows=null,positive=true}){let val=typeof value==='number'?fmt(value,1):value;let color=target!=null&&Number.isFinite(Number(value))?(positive?Number(value)>=target:Number(value)<=target):null;let history=Array.isArray(series)&&series.length>=2?spark(series,target):'';return `<button class="p12-kpi" data-p12="kpi:${h(key||name)}" aria-label="查看${h(name)}指标定义"><span class="p12-kpi-label">${h(name)} <i title="点击查看分子、分母、目标与样本" class="p12-info">ⓘ</i></span><strong>${h(val)}${h(unit)}</strong><small>${target!=null?`目标 ${fmt(target,1)}${unit} · <em class="${color===null?'':color?'ok':'bad'}">${color===null?'待核':color?'达标':'未达标'}</em>`:'目标未设定 · 不推断达标'}</small><span class="p12-kpi-spark">${history}</span><span class="p12-kpi-foot">${h(source||owner||'口径可下钻')} ${delta!=null?` · 较上期 ${fmt(delta,1)}pp`:''}</span></button>`}
function spark(vals,target){const nums=vals.map(x=>N(typeof x==='object'?x.value:x)),hi=Math.max(...nums,target||0,1),lo=Math.min(...nums,0),coords=nums.map((v,i)=>`${2+96*i/(nums.length-1)},${30-26*(v-lo)/Math.max(hi-lo,1)}`).join(' ');let y=30-26*((target||0)-lo)/Math.max(hi-lo,1);return `<svg viewBox="0 0 100 34" preserveAspectRatio="none" role="img" aria-label="模拟趋势"><polyline points="${coords}" stroke="#547f8a" stroke-width="2" fill="none"/>${target!=null?`<path d="M0 ${y} H100" stroke="#b8823a" stroke-dasharray="4 3" fill="none"/>`:''}</svg>`}
function six(cards,history){while(cards.length<6)cards.push({name:'口径与证据',value:'ⓘ',source:'展开查看原始单据 / 定义与数据来源'});return `<div class="p12-kpis">${cards.slice(0,6).map(kpicard).join('')}</div>`}
function box(title,content,note=''){window.PharmaV14?.registerChart(title,note);return `<article class="p12-box"><div class="p12-box-head"><h3>${h(title)}</h3><button type="button" data-p12="explain:${h(title)}" aria-label="图表说明">ⓘ</button></div>${content}${note?`<div class="p12-note">${h(note)}</div>`:''}</article>`}
function grid(...xs){return `<div class="p12-grid">${xs.join('')}</div>`}
function waterfall(rows,labels){const arr=rows.map((x,i)=>({label:labels?.[i]||x.label,value:N(x.value||x.count)})),max=Math.max(1,...arr.map(x=>Math.abs(x.value)));return `<div class="p12-bar-list">${arr.map(x=>`<button ${window.PharmaV14?.chartAttrs(x.label,rows)||`data-p12="select:${h(x.label)}"`} title="按此分类筛选明细"><span>${h(x.label)}</span><i style="width:${Math.min(100,Math.abs(x.value)/max*100)}%" class="${x.value<0?'good':''}"></i><b>${fmt(x.value,1)}</b></button>`).join('')}</div>`}
function donut(rows,caption=''){let total=sum(rows,x=>x.value??x.count),i=0,colors=['#2c5f6b','#527e89','#779aa0','#9cb7bd','#bbcdd0'];let stop=rows.map((r,j)=>{const before=i;i+=(N(r.value??r.count)/Math.max(total,1))*100;return `${colors[j%colors.length]} ${before}% ${i}%`}).join(',');return `<div class="p12-donut-wrap"><div class="p12-donut" style="background:conic-gradient(${stop||'#e5eced 0% 100%'})"><span>${fmt(total)}</span></div><div class="p12-legend">${rows.map((r,j)=>`<button ${window.PharmaV14?.chartAttrs(r.label,rows)||`data-p12="select:${h(r.label)}"`}><i style="background:${colors[j%colors.length]}"></i>${h(r.label)} <b>${total?pct(100*N(r.value??r.count)/total):'—'}</b></button>`).join('')}</div></div>${caption?`<small>${h(caption)}</small>`:''}`}
function line(rows,x,y,target=null,y2=null){if(!rows||rows.length<2)return '<p class="p12-empty">需要至少两期可比较数据；请导入同期价格、需求或计划记录。</p>';let vals=rows.flatMap(r=>[N(r[y]),...(y2?[N(r[y2])]:[])]),max=Math.max(1,...vals,target||0),w=640,ww=590;const xx=i=>32+i*ww/Math.max(1,rows.length-1),yy=v=>155-N(v)/max*128;let points=k=>rows.map((r,i)=>`${xx(i)},${yy(r[k])}`).join(' ');return `<svg class="p12-chart" viewBox="0 0 660 194" role="img" aria-label="${h(y)}趋势"><path d="M32 155H630" stroke="#d2dfe1"/>${target!=null?`<path d="M32 ${yy(target)}H630" stroke="#b8823a" stroke-dasharray="5 4"/>`:''}<polyline points="${points(y)}" fill="none" stroke="#2c5f6b" stroke-width="3"/>${y2?`<polyline points="${points(y2)}" fill="none" stroke="#86a1a4" stroke-width="2"/>`:''}${rows.map((r,i)=>`<text x="${xx(i)}" y="183" font-size="9" fill="#63767e" text-anchor="middle">${h(String(r[x]??'').slice(-6))}</text><circle cx="${xx(i)}" cy="${yy(r[y])}" r="3" fill="#2c5f6b"><title>${h(r[x])}: ${h(r[y])}</title></circle>`).join('')}</svg>`}
function groupedBars(rows,keyA='benchmark_price',keyB='actual_price'){let max=Math.max(1,...rows.flatMap(r=>[N(r[keyA]),N(r[keyB])]));return `<div class="p12-grouped">${rows.map(r=>`<div><b>${h(r.material_id||r.label)}</b><span><i style="width:${100*N(r[keyA])/max}%;background:#93a7b0"></i><small>基准 ${fmt(r[keyA],2)}</small></span><span><i style="width:${100*N(r[keyB])/max}%;background:${N(r[keyB])>N(r[keyA])?'#b4473f':'#527e78'}"></i><small>实际 ${fmt(r[keyB],2)}</small></span></div>`).join('')}</div>`}
function table(rows,columns,id='',footer=''){if(window.PharmaV14)return window.PharmaV14.table(rows,columns,id,footer);let list=rows||[];return `<div class="p12-table-wrap"><table class="p12-table"><thead><tr>${columns.map(x=>`<th>${h(x[0])}</th>`).join('')}${id?'<th>操作</th>':''}</tr></thead><tbody>${list.map((r,i)=>`<tr>${columns.map(([name,fn])=>`<td>${h(typeof fn==='function'?fn(r):r[fn])}</td>`).join('')}${id?`<td>${btn('明细 / 行动',`drill:${id}:${i}`,true)}</td>`:''}</tr>`).join('')}</tbody></table></div>${footer?`<p class="p12-note">${h(footer)}</p>`:''}`}


